/**
 * Reference data shipped with the application (section 9). The reviewed JSON files of
 * data/seed/ are bundled into the main process at build time; the classics of 24cocktails.com
 * (D-036, several megabytes) are generated by scripts/seed/build.ts into
 * resources/seed/recipes-24c.json and read from disk at start-up, like the migrations.
 * Everything is validated again by `loadSeedData` before anything is written.
 */
import { readFileSync } from 'node:fs'
import categories from '../../../data/seed/categories.json'
import glasses from '../../../data/seed/glasses.json'
import ice from '../../../data/seed/ice.json'
import ingredients from '../../../data/seed/ingredients.json'
import recipes from '../../../data/seed/recipes.json'
import type { SeedData } from './load'

/** Name of the generated file of classics, inside the seed folder of resources/. */
export const CLASSICS_FILE = 'recipes-24c.json'

export const BUNDLED_SEED: SeedData = {
  categories: categories as SeedData['categories'],
  glasses: glasses,
  ice: ice,
  ingredients: ingredients as SeedData['ingredients'],
  recipes: recipes as SeedData['recipes'],
}

/** The bundled seed followed by the classics read from `file` (validated by loadSeedData). */
export function withClassics(seed: SeedData, file: string): SeedData {
  const classics = JSON.parse(readFileSync(file, 'utf8')) as SeedData['recipes']
  return { ...seed, recipes: [...seed.recipes, ...classics] }
}
